 @Autowired MockMvc http;@Autowired DocumentoAisladoFixture f;@Autowired DocumentoReservadoController controller;
 MockHttpSession login(String actor)throws Exception{String name=f.d.db.sql.queryForObject("SELECT username FROM staff_account WHERE actor_id=?",String.class,actor);var session=new MockHttpSession();http.perform(post("/nucleo/login").secure(true).session(session).with(csrf()).param("username",name).param("password",actor.equals(f.f.gestion)?f.x.f.f.claveRevisor:f.x.f.passwords.get(name))).andExpect(status().isNoContent());return session;}
 String base(UUID id){return "/nucleo/accesos-reservados/"+id+"/documento";}
 @Test void propuestaCsrfSesionYOriginalConRangeNoAbrenElCaso()throws Exception{
  UUID doc=f.documento();var head=login(f.x.owner);var ti=login(f.ti);var gestion=login(f.f.gestion);String path="/nucleo/casos/"+f.x.cas+"/proteccion-documental/"+doc;String username=f.d.db.sql.queryForObject("SELECT username FROM staff_account WHERE actor_id=?",String.class,f.ti);
  http.perform(get(path+"/destinatario-aislado").param("usuario",username).secure(true).session(head)).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(f.ti));
  var request=new AccesoReservado.Proponer(1,f.ti,f.clock.instant(),f.clock.instant().plusSeconds(120),true,true,"Documento aislado expresamente respaldado");String body=f.d.mapper.writeValueAsString(request);String proposal=path+"/acceso-reservado/solo-documento";
  http.perform(post(proposal).secure(true).session(head).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andExpect(status().isForbidden());var response=http.perform(post(proposal).secure(true).session(head).with(csrf()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andExpect(status().isOk()).andReturn();UUID id=UUID.fromString(f.d.mapper.readTree(response.getResponse().getContentAsString()).path("id").asString());
  http.perform(get(base(id)).secure(true).session(ti)).andExpect(status().isNotFound());http.perform(post("/nucleo/accesos-reservados/"+id+"/aprobar").secure(true).session(gestion).with(csrf()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(f.d.mapper.writeValueAsString(new AccesoReservado.Decidir(0,"Gestión respalda ese archivo y período")))).andExpect(status().isOk());
  http.perform(get(base(id)).secure(true).session(ti)).andExpect(status().isOk()).andExpect(jsonPath("$.nombre").value("antecedente-sintetico.txt")).andExpect(jsonPath("$.caso").doesNotExist()).andExpect(jsonPath("$.comunicacion").doesNotExist()).andExpect(jsonPath("$.contextos").doesNotExist());http.perform(get(base(id)).secure(true).session(login(f.alias))).andExpect(status().isNotFound());
  http.perform(get("/nucleo/casos/"+f.x.cas).secure(true).session(ti)).andExpect(status().isNotFound());http.perform(get("/nucleo/casos").secure(true).session(ti)).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(0));http.perform(get("/nucleo/casos/"+f.x.cas+"/documentos-gestion").secure(true).session(ti)).andExpect(status().isNotFound());
  var ranged=http.perform(get(base(id)+"/original").header("Range","bytes=0-7").secure(true).session(ti)).andExpect(request().asyncStarted()).andReturn();http.perform(asyncDispatch(ranged)).andExpect(status().isPartialContent()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Content-Range","bytes 0-7/"+f.bytes.length)).andExpect(content().bytes(Arrays.copyOfRange(f.bytes,0,8)));
  http.perform(head(base(id)+"/original").secure(true).session(ti)).andExpect(status().isOk()).andExpect(header().longValue("Content-Length",f.bytes.length)).andExpect(content().bytes(new byte[0]));http.perform(get(base(id)+"/original").header("Range","bytes=999999-1000000").secure(true).session(ti)).andExpect(status().isRequestedRangeNotSatisfiable());
  f.f.flow.decidir(f.x.f.a(f.f.gestion),UUID.randomUUID(),id,new AccesoReservado.Decidir(1,"Revocación efectiva con sesión vigente"),"REVOCAR");http.perform(get(base(id)).secure(true).session(ti)).andExpect(status().isNotFound());http.perform(head(base(id)+"/original").secure(true).session(ti)).andExpect(status().isNotFound());
 }
 @Test void metadatosYPaginasNoAutorizanBytesDelOriginal()throws Exception{
  var ti=login(f.ti);UUID text=f.documento(),meta=f.proponer(text,false,false);f.f.aprobar(meta);http.perform(get(base(meta)).secure(true).session(ti)).andExpect(status().isOk()).andExpect(jsonPath("$.consultable").value(false));http.perform(get(base(meta)+"/vista").secure(true).session(ti)).andExpect(status().isNotFound());
  var png=new ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(1,1,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",png);UUID doc=f.documento("imagen-sintetica.png",png.toByteArray()),id=f.proponer(doc,true,false);f.f.aprobar(id);http.perform(get(base(id)+"/vista").secure(true).session(ti)).andExpect(status().isOk()).andExpect(jsonPath("$.paginas").value(1)).andExpect(jsonPath("$.descargable").value(false));var page=http.perform(get(base(id)+"/paginas/1").secure(true).session(ti)).andExpect(request().asyncStarted()).andReturn();http.perform(asyncDispatch(page)).andExpect(status().isOk()).andExpect(content().contentType("image/png")).andExpect(content().bytes(png.toByteArray()));http.perform(get(base(id)+"/original").secure(true).session(ti)).andExpect(status().isNotFound());http.perform(head(base(id)+"/original").secure(true).session(ti)).andExpect(status().isNotFound());http.perform(get(base(id)+"/representacion").secure(true).session(ti)).andExpect(status().isNotFound());
 }
 @Test void revocacionDuranteStreamingDetieneElSiguienteBloque()throws Exception{
  byte[] bytes=new byte[200000];Arrays.fill(bytes,(byte)'A');UUID doc=f.documento("grande-sintetico.txt",bytes),id=f.proponer(doc,true,true);f.f.aprobar(id);var session=login(f.ti);var auth=((SecurityContext)session.getAttribute("SPRING_SECURITY_CONTEXT")).getAuthentication();var request=new MockHttpServletRequest("GET",base(id)+"/original");request.setSecure(true);var response=controller.original(auth,id,request);
  var output=new ByteArrayOutputStream(){boolean revoked;@Override public synchronized void write(byte[] b,int offset,int length){super.write(b,offset,length);if(!revoked){revoked=true;f.f.flow.decidir(f.x.f.a(f.f.gestion),UUID.randomUUID(),id,new AccesoReservado.Decidir(1,"Retiro de permiso tras primer bloque autorizado"),"REVOCAR");}}};assertEquals(404,assertThrows(FalloTecnico.class,()->response.getBody().writeTo(output)).status);assertEquals(65536,output.size());assertEquals(0,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_action WHERE case_id=?",Long.class,f.x.cas.toString()));
 }
 @Test void originalCiudadano11ConFirmaYCustodiaSeConsultaSinReescribirComprobanteNiAck()throws Exception{
  byte[] bytes="ORIGINAL CIUDADANO SINTETICO".getBytes(java.nio.charset.StandardCharsets.UTF_8);UUID operation=UUID.randomUUID(),attachment=UUID.randomUUID();String sha=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));var descriptor=new EntregaCompleta.Adjunto(attachment,"original-sintetico.txt",bytes.length,sha,"text/plain","VALIDADO");
  var c=f.d.mapper.createObjectNode();c.put("version","1.1");c.put("id",operation.toString());c.put("recorridoId",UUID.randomUUID().toString());c.put("tipo","NNA");c.put("recibidaEn",f.clock.instant().toString());c.put("avisoVersion","SINTETICO_1");c.put("aceptaCanalDigital",false);var data=c.putObject("datos");var campos=data.putObject("campos");campos.put("motivo","consulta");campos.put("nna-story","Relato íntegro de prueba sintética sin datos reales");data.putArray("personas");data.putArray("instituciones");data.putArray("adjuntos").add(attachment.toString());c.putArray("adjuntos").add(f.d.mapper.valueToTree(descriptor));var p=c.putArray("personas").addObject();p.put("id","presentador-nna");p.put("rol","PRESENTADOR");p.put("autenticada",false);p.put("modulo11",false);p.putNull("runNumero");p.putNull("runDv");p.put("estadoConsulta","NO_HABILITADO");p.putNull("consultadaEn");p.putNull("consultaRef");p.putObject("discrepancias");var attrs=p.putObject("atributos");for(String key:List.of("primerNombre","segundoNombre","primerApellido","segundoApellido")){var a=attrs.putObject(key);a.put("valor","NOMBRE SINTETICO");a.putNull("codigo");a.put("fuente","DECLARACION_CIUDADANA");a.put("nivel","DECLARADO_NO_CONTRASTADO");a.put("observadoEn",c.path("recibidaEn").asString());a.put("evidencia",UUID.randomUUID().toString());}
  var sources=f.d.mapper.createObjectNode();sources.set("presentador-nna",f.d.mapper.createArrayNode().add(p.path("atributos")).add(p.path("discrepancias")));String content=EntregaCompleta.huella("CONTENIDO",c,f.d.mapper),provenance=EntregaCompleta.huella("PROCEDENCIA",sources,f.d.mapper);var proof=new ComprobanteDigital.Contenido("1.0",operation,Instant.parse(c.path("recibidaEn").asString()),"CUSTODIA_PUBLICA",content,provenance,"FORMULARIO_PUBLICO_DDN","SINTETICO_1");var delivery=new EntregaCompleta(c,content,provenance,ComprobanteDigital.firmar(proof,"nucleo-test",f.d.publicKeys.getPrivate(),f.d.mapper));
  long before=f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_requirement",Long.class);f.files.guardar(operation,descriptor,new ByteArrayInputStream(bytes));UUID com=f.d.recepcion.guardarCompleta(delivery,f.files).registro().comunicacionId();assertEquals(before,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_requirement",Long.class));var u=f.x.f.core.u2();UUID sol=u.distribuir(f.x.f.a(f.x.f.dist),UUID.randomUUID(),com,new NucleoU2.Encaminar(0,new ContratosNucleo.NuevoDestino("UPR","DEMO_SEDE_A",f.x.owner,"AREA_A"),"Clasificación central sintética",null)).id();UUID req=u.asumir(f.x.f.a(f.x.owner),UUID.randomUUID(),sol,new NucleoU2.Asumir(0,f.x.owner,"Asunción legítima de jefatura","Decisión territorial fundada sin cobertura cargada")).id();UUID cas=u.abrirCaso(f.x.f.a(f.x.owner),UUID.randomUUID(),req,new NucleoU2.Apertura(0,f.x.owner,"Objetivo sintético independiente")).id();UUID doc=UUID.fromString(f.d.db.sql.queryForObject("SELECT id FROM institution_document WHERE communication_id=?",String.class,com.toString()));f.x.f.core.contenidos().proteger(f.x.f.a(f.x.owner),UUID.randomUUID(),cas,doc,new ContenidoInstitucional.Proteccion(0,"ORDINARIO","Clasificación expresa del original ciudadano; no se etiqueta como ficha interna"));
  String original=f.d.db.sql.queryForObject("SELECT body FROM institutional_inbox WHERE id=?",String.class,operation.toString()),receipt=f.d.db.sql.queryForObject("SELECT receipt FROM institutional_inbox WHERE id=?",String.class,operation.toString());UUID access=f.f.flow.proponerDocumento(f.x.f.a(f.x.owner),UUID.randomUUID(),cas,doc,new AccesoReservado.Proponer(1,f.ti,f.clock.instant(),f.clock.instant().plusSeconds(120),true,true,"Solo el original ciudadano expresamente autorizado")).id();f.f.aprobar(access);var session=login(f.ti);http.perform(get(base(access)).secure(true).session(session)).andExpect(status().isOk()).andExpect(jsonPath("$.origen").value("INGRESO_CIUDADANO")).andExpect(jsonPath("$.sha256").value(sha));var response=http.perform(get(base(access)+"/original").secure(true).session(session)).andExpect(request().asyncStarted()).andReturn();http.perform(asyncDispatch(response)).andExpect(status().isOk()).andExpect(content().bytes(bytes));http.perform(get("/nucleo/comunicaciones/"+com).secure(true).session(session)).andExpect(status().isNotFound());assertEquals(original,f.d.db.sql.queryForObject("SELECT body FROM institutional_inbox WHERE id=?",String.class,operation.toString()));assertEquals(receipt,f.d.db.sql.queryForObject("SELECT receipt FROM institutional_inbox WHERE id=?",String.class,operation.toString()));assertTrue(f.d.db.sql.queryForObject("SELECT ack_pending FROM institutional_inbox WHERE id=?",Boolean.class,operation.toString()));assertEquals(before+1,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_requirement",Long.class));
 }
